  "    <button class=\"taxonomy-item\" data-taxonomy=\"auth\"><span class=\"taxonomy-icon auth\"><svg class=\"icon\"><use href=\"#i-shield\"/></svg></span><span><strong>Authentication</strong><small>admin.login</small></span><em id=\"tax-auth\">\u2014</em></button>",
  "    <button class=\"taxonomy-item\" data-taxonomy=\"provider\"><span class=\"taxonomy-icon provider\"><svg class=\"icon\"><use href=\"#i-db\"/></svg></span><span><strong>Provider Control</strong><small>enable \u00b7 disable \u00b7 credential</small></span><em id=\"tax-provider\">\u2014</em></button>",
  "    <button class=\"taxonomy-item\" data-taxonomy=\"model\"><span class=\"taxonomy-icon model\"><svg class=\"icon\"><use href=\"#i-cube\"/></svg></span><span><strong>Model Control</strong><small>model.enable \u00b7 model.disable</small></span><em id=\"tax-model\">\u2014</em></button>",
  "    <button class=\"taxonomy-item\" data-taxonomy=\"health\"><span class=\"taxonomy-icon health\"><svg class=\"icon\"><use href=\"#i-heart\"/></svg></span><span><strong>Health Evidence</strong><small>provider.health-test</small></span><em id=\"tax-health\">\u2014</em></button>",
  "    <button class=\"taxonomy-item\" data-taxonomy=\"other\"><span class=\"taxonomy-icon other\"><svg class=\"icon\"><use href=\"#i-nodes\"/></svg></span><span><strong>Other</strong><small>Unclassified persisted actions</small></span><em id=\"tax-other\">\u2014</em></button>",
